import math

def num(x):
    # a negative number goes in parentheses, as you'd write it by hand
    if x < 0:
        return f"({x})"
    return f"{x}"

def multiply(f, g):
    h = [0] * (len(f) + len(g) - 1)
    for i in range(len(f)):
        for j in range(len(g)):
            h[i + j] = h[i + j] + f[i] * g[j]
    return h

count = int(input())
for t in range(count):
    p = int(input())
    q = int(input())
    n = int(input())
    j = int(input())
    print(f"coefficient of x^{j} in ({p}x + {num(q)})^{n}")
    if j > n:
        print(f"  {j} > {n}, so no term has x^{j}: 0")
    else:
        k = n - j
        c = math.comb(n, k) * p**j * q**k
        print(f"  k = {n} - {j} = {k}")
        print(f"  C({n}, {k}) * {p}^{j} * {num(q)}^{k} = {math.comb(n, k)} * {p**j} * {num(q**k)} = {c}")
    poly = [1]
    for i in range(n):
        poly = multiply(poly, [q, p])
    if j > n:
        print("  multiplied out: 0")
    else:
        print(f"  multiplied out: {poly[j]}")
